using System.Linq;using NUnit.Framework;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
namespace Rootborn.Tests.EditMode.UI.StudentLife{public sealed class SchoolChalkboardMoldingArtTests{
[SetUp]public void RequireSavedEditorState(){for(int i=0;i<UnityEngine.SceneManagement.SceneManager.sceneCount;i++)Assert.That(UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).isDirty,Is.False,"Never discard unsaved scenes");EditorSceneManager.OpenScene("Assets/Scenes/Boot.unity",OpenSceneMode.Single);}
[Test]public void DedicatedSpriteRetainsCrispReviewedFloorPivot(){const string path="Assets/Art/SchoolPixels/Comfy31/school_chalkboard.png";var s=AssetDatabase.LoadAssetAtPath<Sprite>(path);Assert.That(s,Is.Not.Null);Assert.That(s.rect.size,Is.EqualTo(new Vector2(96,64)));Assert.That(s.pivot,Is.EqualTo(new Vector2(48,32)));Assert.That(s.pixelsPerUnit,Is.EqualTo(48));var i=(TextureImporter)AssetImporter.GetAtPath(path);Assert.That(i.filterMode,Is.EqualTo(FilterMode.Point));Assert.That(i.mipmapEnabled,Is.False);Assert.That(i.textureCompression,Is.EqualTo(TextureImporterCompression.Uncompressed));Assert.That(i.npotScale,Is.EqualTo(TextureImporterNPOTScale.None));var e=UnityEditor.AddressableAssets.AddressableAssetSettingsDefaultObject.Settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(path));Assert.That(e,Is.Not.Null);Assert.That(e.address,Is.EqualTo("sprites/school/comfy31/chalkboard"));CollectionAssert.Contains(e.labels,"SchoolPixels");Assert.That(e.parentGroup.Name,Is.EqualTo("Sprites"));}
[Test]public void OnlyExistingSchoolChalkboardUsesDedicatedMolding(){var scene=EditorSceneManager.OpenPreviewScene("Assets/Scenes/School.unity");try{var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var root=all.Single(t=>t.name=="Chalkboard");var v=root.Find("Visual").GetComponent<SpriteRenderer>();Assert.That(v.sprite.name,Is.EqualTo("school_chalkboard"));Assert.That(root.GetComponent<UnityEngine.Rendering.SortingGroup>().sortingOrder,Is.EqualTo(10096));Assert.That(v.sortingOrder,Is.EqualTo(0));Assert.That(root.localPosition,Is.EqualTo(new Vector3(7.5f,-2,0)));Assert.That(v.transform.localPosition.y,Is.EqualTo(32f/48f).Within(.0001f));Assert.That(root.Find("SchoolWallClockComfy31"),Is.Not.Null);Assert.That(root.Find("SchoolWallWindowComfy31"),Is.Not.Null);Assert.That(all.SelectMany(t=>t.GetComponents<SpriteRenderer>()).Count(r=>r.sprite!=null&&r.sprite.name=="school_chalkboard"),Is.EqualTo(1),"New molding affects one fixed visual;the original classroom sprite remains available");Assert.That(AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Art/SchoolPixels/sprites/chalkboard.png"),Is.Not.Null);}finally{EditorSceneManager.ClosePreviewScene(scene);}}
}}
